option.echartFormatter:
/**
 * echart通用性配置
 * @params data 数据参数
 * @return 输出配置， 可在return前做一些数据处理操作等
 * 备注：第三方Echarts配置---start<-替换代码区域->end
 */
(data)=>{
  // 声明option配置，匹配Echart实例的option变量
  let option = {}
  // console.log(data)

  // ------ 输出配置赋值-start ------
  option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: {
        type: 'cross',
        crossStyle: {
          color: '#999999'
        }
      }
    },
    legend: {
      data: ['系列一', '系列二'],
      textStyle: {
        fontSize: 16,
        color: '#ffffff'
      }
    },
    xAxis: [
      {
        type: 'category',
        data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'],
        axisPointer: {
          type: 'shadow'
        },
        axisLabel: {
          fontSize: 16,
          color: '#ffffff'
        }
      }
    ],
    yAxis: [
      {
        type: 'value',
        splitLine: {
          lineStyle: {
            color: '#726c6c'
          }
        },
        axisLabel: {
          formatter: '{value} ml',
          fontSize: 16,
          color: '#ffffff'
        }
      },
      {
        type: 'value',
        splitLine: {
          show: false
        },
        axisLabel: {
          formatter: '{value} °C',
          fontSize: 16,
          color: '#ffffff'
        }
      }
    ],
    series: [
      {
        name: '系列一',
        type: 'bar',
        barMaxWidth: 30,
        itemStyle: {
          borderColor: '#188df0',
          color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
            { offset: 0, color: '#83bff6' },
            { offset: 0.5, color: '#188df0' },
            { offset: 1, color: '#188df0' }
          ])
        },
        tooltip: {
          valueFormatter: function (value) {
            return value + ' ml'
          }
        },
        data: [ 10, 30, 20, 40, 50 ]
      },
      {
        name: '系列二',
        type: 'line',
        yAxisIndex: 1,
        tooltip: {
          valueFormatter: function (value) {
            return value + ' °C'
          }
        },
        data: [10, 30, 20, 40, 50]
      }
    ]
  }
  // ------ 输出配置赋值-end ------

  // 数据参数处理

  // 输出配置
  return option
}
